SCHEMA = {
    "/users": {
        "POST": {
            "required": {"name": str, "age": int},
        }
    }
}


def validate_request(path, method, body):
    spec = SCHEMA[path][method]["required"]
    errors = []
    for field, field_type in spec.items():
        if field not in body:
            errors.append(f"missing field: {field}")
        elif not isinstance(body[field], field_type):
            errors.append(f"wrong type for {field}: expected {field_type.__name__}")
    return errors


def test_valid_request():
    errors = validate_request("/users", "POST", {"name": "Alice", "age": 30})
    assert errors == [], f"expected no errors, got {errors}"
    print("test_valid_request: PASS")


def test_missing_field():
    errors = validate_request("/users", "POST", {"name": "Alice"})
    assert errors == ["missing field: age"], errors
    print("test_missing_field: PASS")


def test_wrong_type():
    errors = validate_request("/users", "POST", {"name": "Alice", "age": "30"})
    assert errors == ["wrong type for age: expected int"], errors
    print("test_wrong_type: PASS")


test_valid_request()
test_missing_field()
test_wrong_type()
